/**
 * Filter accepted by the issue repository, service layer and list UI alike.
 * `ME` is resolved to the acting user by the service; `null` assignee means
 * unassigned. The URL codec and the filter schema both produce this shape.
 */
export interface IssueFilter {
  readonly projectId?: ProjectId;
  readonly status?: readonly IssueStatus[];
  readonly priority?: readonly IssuePriority[];
  readonly assigneeId?: UserId | typeof ME | null;
  readonly authorId?: UserId | typeof ME;
  readonly labelIds?: readonly LabelId[];
  readonly query?: string;
  /** A calendar date (whole day included) or a full timestamp (strictly before). */
  readonly dueBefore?: IsoTimestamp | IsoDate;
  /** Adds archived issues to the live ones. */
  readonly includeArchived?: boolean;
  /** Lists archived issues and nothing else. Wins over `includeArchived`. */
  readonly archivedOnly?: boolean;
}

