export type IssueStatus =
  | "backlog"
  | "todo"
  | "in_progress"
  | "in_review"
  | "done"
  | "canceled";

export const ISSUE_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
];

/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Every status that is not closed. ADR 0009: `open` is this group. */
export const OPEN_ISSUE_STATUSES: readonly IssueStatus[] = ISSUE_STATUSES.filter(
  (status) => !CLOSED_ISSUE_STATUSES.includes(status),
);

/** Group names accepted wherever a status filter is read (ADR 0009, rule 3). */
export const ISSUE_STATUS_GROUPS = ["open", "closed"] as const;
export type IssueStatusGroup = (typeof ISSUE_STATUS_GROUPS)[number];

/** A status as written in a filter: one of the six, or a group name. */
export type IssueStatusFilterValue = IssueStatus | IssueStatusGroup;

export const ISSUE_STATUS_FILTER_VALUES: readonly IssueStatusFilterValue[] = [
  ...ISSUE_STATUSES,
  ...ISSUE_STATUS_GROUPS,
];

/**
 * Expands group names into their members, keeping first-seen order and
 * dropping repeats. A plain status passes through unchanged.
 */
export function expandStatusFilter(
  values: readonly IssueStatusFilterValue[],
): IssueStatus[] {
  const expanded: IssueStatus[] = [];
  for (const value of values) {
    const members: readonly IssueStatus[] =
      value === "open"
        ? OPEN_ISSUE_STATUSES
        : value === "closed"
          ? CLOSED_ISSUE_STATUSES
          : [value];
    for (const member of members) {
      if (!expanded.includes(member)) expanded.push(member);
