import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { parseIssueFilterParams, issueFilterToParams } from "@/hooks/issue-filter-params";
import { issueFilterSchema } from "@/schemas/issue";
import { exportIssuesSchema } from "@/schemas/export";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let t: Tenant;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); t = await createTenant("scratch-filter"); });
afterAll(() => cleanup());

async function ins(over: Record<string, unknown>, extra: Record<string, unknown> = {}) {
  const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  return issueRepo.insertIssue({ ...issueInput(t.org.id, t.project.id, over as never), ...extra } as never, t.userIds.owner, n);
}

describe("scratch", () => {
  it("behaves per ADR 0009", async () => {
    const l1 = await labelRepo.insertLabel({ orgId: t.org.id, name: "bug", color: "#ef4444", description: null });
    const l2 = await labelRepo.insertLabel({ orgId: t.org.id, name: "regression", color: "#ef4444", description: null });
    const both = await ins({ title: "both labels" }, { labelIds: [l1.id, l2.id] });
    const onlyOne = await ins({ title: "one label" }, { labelIds: [l1.id] });
    const unassigned = await ins({ title: "nobody" }, { assigneeId: null, dueAt: "2026-03-15T23:30:00.000Z" });
    const assigned = await ins({ title: "someone", assigneeId: t.userIds.member }, { dueAt: "2026-03-16T00:00:00.000Z" });
    const done = await ins({ title: "finished" }, { status: "done" });
    const archived = await ins({ title: "gone" });
    await issueRepo.archiveIssue(t.org.id, archived.id);

    const all = (q: Record<string, unknown>) =>
      issueRepo.listIssues({ orgId: t.org.id, limit: 100, cursor: null, ...q } as never);

    const labelled = await all({ labelIds: [l1.id, l2.id] });
    expect(labelled.items.map((i) => i.id)).toEqual([both.id]);
    expect(labelled.total).toBe(1);

    const un = await all({ assigneeId: null });
    expect(un.items.map((i) => i.id)).not.toContain(assigned.id);
    expect(un.items.map((i) => i.id)).toContain(unassigned.id);
    expect(un.total).toBe(un.items.length);

    const dayBefore = await all({ dueBefore: "2026-03-15" });
    expect(dayBefore.items.map((i) => i.id)).toContain(unassigned.id);
    expect(dayBefore.items.map((i) => i.id)).not.toContain(assigned.id);
    const ts = await all({ dueBefore: "2026-03-15T23:30:00.000Z" });
    expect(ts.items.map((i) => i.id)).not.toContain(unassigned.id);

    const onlyArch = await all({ archivedOnly: true });
    expect(onlyArch.items.map((i) => i.id)).toEqual([archived.id]);
    expect(onlyArch.total).toBe(1);

    const open = await all({ status: ["backlog", "todo", "in_progress", "in_review"] });
    expect(open.items.map((i) => i.id)).not.toContain(done.id);

    const openGroup = await all({ status: ["open"] });
    expect(openGroup.items.map((i) => i.id)).not.toContain(done.id);
    expect(openGroup.items.map((i) => i.id)).toContain(unassigned.id);
  });

  it("codec and schema agree", () => {
    const f = parseIssueFilterParams(new URLSearchParams("status=open,done&assignee=none&archived=only&due_before=2026-03-15&label=a,b"));
    expect(f.status).toEqual(["backlog", "todo", "in_progress", "in_review", "done"]);
    expect(f.assigneeId).toBeNull();
    expect(f.archivedOnly).toBe(true);
    expect(issueFilterToParams(f).archived).toBe("only");
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, ...f }).success).toBe(true);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "2026-03-15" }).success).toBe(true);
    expect(exportIssuesSchema.safeParse({ orgId: t.org.id, status: ["open"], assigneeId: "me" }).success).toBe(true);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["bogus"] }).success).toBe(false);
  });
});
